import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.99, D: 33.33, E: 100, F: 100.01 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withServer(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  return withServer(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    return (await res.json()).total
  })
}

// These pin CURRENT behaviour so a refactor that changes totals fails loudly.
test('single item, no discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 1 }]), 10)
})

test('multiple items are summed', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 3 }]), 95)
})

test('exactly 100 gets no discount (threshold is strictly > 100)', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 100)
})

test('just over 100 gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 90) // 90.009 floored
})

test('larger order: 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 10 }]), 225)
  assert.equal(await totalFor([{ sku: 'E', qty: 10 }]), 900)
})

test('discount applies to whole order, not just the part above 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
})

test('KNOWN QUIRK: total is floored to whole euros, cents are dropped', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 0)
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33)
  assert.equal(await totalFor([{ sku: 'D', qty: 4 }]), 119) // 133.32 * 0.9 = 119.988
})

test('total is persisted and returned by GET', async () => {
  await withServer(async (base) => {
    const created = await (await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'B', qty: 10 }] }) })).json()
    const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
    assert.equal(fetched.total, 225)
  })
})
EOF
