  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33)
  assert.equal(await totalFor([{ sku: 'D', qty: 4 }]), 119) // 133.32 * 0.9 = 119.988
})

test('total is persisted and returned by GET', async () => {
  await withServer(async (base) => {
    const created = await (await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'B', qty: 10 }] }) })).json()
    const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
    assert.equal(fetched.total, 225)
  })
})
